// AUTO-GENERATED by scripts/bake-effect-units.ts from Reference/XML/Infos.
// Do not edit by hand — re-run `npm run bake:effect-units`.
//
// The effect units a unit can carry, their glyphs, and the six columns
// `Unit.modifiedAttack` / `modifiedDefense` (Unit.cs:6366) are summed from.
// Read through `$lib/game-detail/unit-combat`, never directly.

export interface EffectUnit {
	/** The game's own name, from `<GenderedName>` — never formatEnum. */
	readonly name: string;
	/**
	 * `<zIconName>` — the key the `effect-units` sprite category takes,
	 * which is NOT the zType for 47 of the entries a unit can carry.
	 */
	readonly icon: string;
	/**
	 * The unit types the display gate `Game.isEffectUnitValid`
	 * (Game.cs:14409) lets it land on. Absent means every one of them — so
	 * an unlisted unit type on a gated entry drops the effect rather than
	 * claiming one the game denies. Only the channels that do not pass
	 * `bForce` are gated; a unit's innate and promoted effect units are not.
	 */
	readonly validUnits?: readonly string[];
	// ── The six the game's attack and defense are summed from ──
	readonly strengthModifier?: number;
	readonly attackModifier?: number;
	readonly perLevelAttackModifier?: number;
	readonly defenseModifier?: number;
	/** Paid only while the unit is damaged (`ifDamagedModifier`, Unit.cs:6786). */
	readonly damagedUsModifier?: number;
	/** Paid only while the unit has a general (`hasGeneralModifier`, Unit.cs:6836). */
	readonly hasGeneralModifier?: number;
	/**
	 * `aeEffectUnitUnlock` and `AdjacentEffectUnit`, which
	 * `changeEffectUnit` (Unit.cs:5061) adds alongside this one under the
	 * same source — so one seed can put several effect units on the unit.
	 */
	readonly unlocks?: readonly string[];
}

