/** A trait that confers an effect unit on a unit its holder leads. */
export interface GeneralTrait {
	/** `<GeneralEffectUnit>` — conferred by any general who holds the trait. */
	readonly general?: string;
	/** `<LeaderEffectUnit>` — only for a general who is their own leader. */
	readonly leader?: string;
}

