// The FAMILY channel: the effect unit the band its own player's opinion of
// its family falls in confers, which `Unit.changeFamily` (Unit.cs:4344)
// adds — gated, like the trait channel. The neutral band confers none and
// so has no entry.
export const FAMILY_OPINION_EFFECT_UNITS: Readonly<Record<string, string>> = {
	OPINIONFAMILY_FURIOUS: "EFFECTUNIT_OPINIONFAMILY_FURIOUS",
	OPINIONFAMILY_ANGRY: "EFFECTUNIT_OPINIONFAMILY_ANGRY",
	OPINIONFAMILY_UPSET: "EFFECTUNIT_OPINIONFAMILY_UPSET",
	OPINIONFAMILY_PLEASED: "EFFECTUNIT_OPINIONFAMILY_PLEASED",
	OPINIONFAMILY_FRIENDLY: "EFFECTUNIT_OPINIONFAMILY_FRIENDLY",
};

/** What one effect player puts on a unit, as the three forms it takes. */
export interface EffectPlayerConferral {
	/** `meEffectUnit` — every unit the player owns. */
	readonly all?: string;
	/**
	 * `maeEffectUnitTrait[trait]` and `maeEffectUnit[unit]`, both resolved
	 * into unit types at bake time — the unit-trait arm tests
	 * `info().maeUnitTrait`, which is unit.xml data, so the runtime needs no
	 * unit-trait table of its own.
	 */
	readonly byUnit?: Readonly<Record<string, string>>;
}

